    font-weight: 700;
    flex-shrink: 0;
  }
  .section-header h2 {
    font-size: 1.35rem;
    font-weight: 700;
    color: var(--primary);
  }

  /* Cards */
  .card {
    background: var(--card-bg);
    border: 1px solid var(--border);
    border-radius: 10px;
    padding: 24px 28px;
    margin-bottom: 20px;
