  .takeaway-card.warn { border-top-color: var(--accent2); }
  .takeaway-card.green { border-top-color: var(--accent3); }
  .takeaway-number {
    font-size: 28px;
    font-weight: 700;
    color: var(--accent);
    line-height: 1;
    margin-bottom: 8px;
  }
  .takeaway-card.warn .takeaway-number { color: var(--accent2); }
  .takeaway-card.green .takeaway-number { color: var(--accent3); }
  .takeaway-title { font-size: 14px; font-weight: 700; color: var(--primary); margin-bottom: 6px; }
  .takeaway-desc { font-size: 13px; color: var(--muted); line-height: 1.5; }

