    border: 1px solid #b8d8e8;
  }
  .topic-pill.large {
    font-size: 14px;
    padding: 7px 18px;
    background: #0d5f7a;
    color: white;
    border-color: transparent;
  }
  .topic-pill.medium {
    background: #dde9f5;
    color: #1a3a5c;
  }
</style>
</head>
