// Simple linear trend
const n = oaRates.length;
const sumX = n*(n-1)/2;
const sumY = oaRates.reduce((a,b)=>a+b,0);
const sumXY = oaRates.reduce((s,v,i)=>s+i*v,0);
const sumX2 = oaRates.reduce((s,v,i)=>s+i*i,0);
const slope = (n*sumXY - sumX*sumY)/(n*sumX2 - sumX*sumX);
const intercept = (sumY - slope*sumX)/n;
const trendLine = oaRates.map((_,i)=>+(intercept+slope*i).toFixed(1));

new Chart(document.getElementById('oaMonthlyChart'), {
